with with_windows as (select *, ntile(4) over (order by cost, id) cost_bucket, sum(cost) over w_running running_cost from shipments window w_running as (partition by carrier, status order by shipped_date, id rows between unbounded preceding and current row)) select s.id, s.order_id, s.delivered_date, s.cost, s.status, s.cost_bucket, s.running_cost, (select max(o2.unit_price) from order_items o2 where o2.order_id = s.order_id) as max_order_item_unit_price from with_windows s
